PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, plan TEXT NOT NULL DEFAULT 'demo', status TEXT NOT NULL DEFAULT 'active', is_demo INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS units (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, name TEXT NOT NULL, city TEXT NOT NULL DEFAULT '', timezone TEXT NOT NULL DEFAULT 'America/Sao_Paulo', status TEXT NOT NULL DEFAULT 'active', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_accounts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, email TEXT NOT NULL, full_name TEXT NOT NULL, role TEXT NOT NULL, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, password_iterations INTEGER NOT NULL DEFAULT 310000, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, tenant_id TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT);
CREATE INDEX IF NOT EXISTS sessions_token_idx ON sessions(token_hash, expires_at);
CREATE TABLE IF NOT EXISTS auth_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, identity_key TEXT NOT NULL, attempted_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS auth_attempts_key_idx ON auth_attempts(identity_key, attempted_at);
CREATE TABLE IF NOT EXISTS patients (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, code TEXT NOT NULL, full_name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', birth_date TEXT, source TEXT NOT NULL DEFAULT 'Indicação', status TEXT NOT NULL DEFAULT 'Ativo', notes TEXT NOT NULL DEFAULT 'Cadastro fictício de demonstração', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS patients_tenant_idx ON patients(tenant_id,is_archived);
CREATE TABLE IF NOT EXISTS professionals (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, full_name TEXT NOT NULL, specialty TEXT NOT NULL, registration TEXT NOT NULL DEFAULT 'DEMO', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Ativo', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, name TEXT NOT NULL, specialty TEXT NOT NULL DEFAULT '', duration_minutes INTEGER NOT NULL DEFAULT 30, price_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Ativo', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rooms (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, name TEXT NOT NULL, resource_type TEXT NOT NULL DEFAULT 'Consultório', status TEXT NOT NULL DEFAULT 'Ativo', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, patient_id TEXT, professional_id TEXT, service_id TEXT, room_id TEXT, starts_at TEXT NOT NULL, ends_at TEXT, status TEXT NOT NULL DEFAULT 'Agendado', notes TEXT NOT NULL DEFAULT 'Agendamento fictício', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS appointments_tenant_date_idx ON appointments(tenant_id,starts_at,is_archived);
CREATE TABLE IF NOT EXISTS clinical_records (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, patient_id TEXT, appointment_id TEXT, professional_id TEXT, record_type TEXT NOT NULL DEFAULT 'Evolução', summary TEXT NOT NULL DEFAULT 'Registro sintético sem conteúdo assistencial.', status TEXT NOT NULL DEFAULT 'Rascunho', author_id TEXT, is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, patient_id TEXT, appointment_id TEXT, professional_id TEXT, document_type TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Rascunho', issued_at TEXT, is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, patient_id TEXT, description TEXT NOT NULL, amount_cents INTEGER NOT NULL DEFAULT 0, method TEXT NOT NULL DEFAULT 'Pix', status TEXT NOT NULL DEFAULT 'Recebido', due_date TEXT, settled_at TEXT, is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, description TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Operacional', amount_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'A pagar', due_date TEXT, settled_at TEXT, is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS insurance_plans (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, name TEXT NOT NULL, registration_code TEXT NOT NULL DEFAULT 'DEMO', contact TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Ativo', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS insurance_claims (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, plan_id TEXT, patient_id TEXT, reference_code TEXT NOT NULL, amount_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Em análise', submitted_at TEXT, is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_items (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, code TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Material', quantity REAL NOT NULL DEFAULT 0, minimum_quantity REAL NOT NULL DEFAULT 0, unit_label TEXT NOT NULL DEFAULT 'un', lot TEXT NOT NULL DEFAULT 'DEMO', expires_on TEXT, status TEXT NOT NULL DEFAULT 'Ativo', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, name TEXT NOT NULL, contact TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Ativo', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS communications (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, patient_id TEXT, channel TEXT NOT NULL DEFAULT 'E-mail fictício', subject TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Programada', scheduled_at TEXT, consent_status TEXT NOT NULL DEFAULT 'Fictício', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, unit_id TEXT, title TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Operação', assigned_to TEXT NOT NULL DEFAULT '', due_at TEXT, status TEXT NOT NULL DEFAULT 'Pendente', priority TEXT NOT NULL DEFAULT 'Normal', is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, actor_id TEXT, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platform_subscriptions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, plan_name TEXT NOT NULL, status TEXT NOT NULL, seats INTEGER NOT NULL DEFAULT 1, renews_at TEXT, is_archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
